#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
long long target;scanf("%lld",&target);
unordered_map<long long,int>seen;
for(int i=0;i<n;++i){auto it=seen.find(target-a[i]);
if(it!=seen.end()){printf("%d %d\n",it->second,i);return 0;}seen.emplace(a[i],i);}
printf("-1\n");return 0;}

